static int ui_demo_netinfo_connect(const char *host, const char *port,
                                   int timeout_ms)
{
  struct addrinfo hints;
  struct addrinfo *result = NULL;
  struct addrinfo *cur;
  int ret = -EHOSTUNREACH;

  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_STREAM;
  hints.ai_protocol = IPPROTO_TCP;

  ret = getaddrinfo(host, port, &hints, &result);
  if (ret != 0 || result == NULL)
    {
      syslog(LOG_WARNING, "%s: dns failed host=%s ret=%d\n",
             UI_DEMO_NETINFO_LOG_TAG, host, ret);
      return -EHOSTUNREACH;
    }

  for (cur = result; cur != NULL; cur = cur->ai_next)
    {
      int sock;
      int flags;
      int rc;

      sock = socket(cur->ai_family, cur->ai_socktype, cur->ai_protocol);
      if (sock < 0)
        {
          ret = errno == 0 ? -EIO : -errno;
          continue;
        }

      flags = fcntl(sock, F_GETFL, 0);
      if (flags < 0)
        {
          flags = 0;
        }

      (void)fcntl(sock, F_SETFL, flags | O_NONBLOCK);
      rc = connect(sock, cur->ai_addr, cur->ai_addrlen);
      if (rc < 0 && errno == EINPROGRESS)
        {
          fd_set wfds;
          struct timeval tv;

          FD_ZERO(&wfds);
          FD_SET(sock, &wfds);
          tv.tv_sec = timeout_ms / 1000;
          tv.tv_usec = (timeout_ms % 1000) * 1000;
          rc = select(sock + 1, NULL, &wfds, NULL, &tv);
          if (rc > 0)
            {
              int err = 0;
              socklen_t err_len = sizeof(err);

              if (getsockopt(sock, SOL_SOCKET, SO_ERROR,
                             &err, &err_len) < 0 || err != 0)
                {
                  rc = -1;
                  errno = err == 0 ? EIO : err;
                }
              else
                {
                  rc = 0;
                }
            }
          else if (rc == 0)
            {
              rc = -1;
              errno = ETIMEDOUT;
            }
        }

      if (rc == 0)
        {
          struct timeval tv;

          (void)fcntl(sock, F_SETFL, flags);
          tv.tv_sec = timeout_ms / 1000;
          tv.tv_usec = (timeout_ms % 1000) * 1000;
          (void)setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO,
                           &tv, sizeof(tv));
          (void)setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO,
                           &tv, sizeof(tv));
          freeaddrinfo(result);
          return sock;
        }

      ret = errno == 0 ? -EIO : -errno;
      close(sock);
    }

  freeaddrinfo(result);
  return ret;

